function canMakeArithmeticProgression(arr) {
  const n = arr.length;
  const low = Math.min(...arr);
  const high = Math.max(...arr);
  if (low === high) return true;
  if ((high - low) % (n - 1) !== 0) return false;
  const gap = (high - low) / (n - 1);
  const values = new Set(arr);
  if (values.size !== n) return false;
  for (let k = 0; k < n; k++) if (!values.has(low + k * gap)) return false;
  return true;
}

