function generate(rand, size) {
  const limit = size === 'large' ? 1000000 : 12;
  const n = size === 'large' ? 600 + Math.floor(rand() * 401) : 2 + Math.floor(rand() * 7);
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const roll = rand();
  let arr;
  if (roll < 0.25) {
    arr = Array.from({ length: n }, () => pick(-limit, limit));
  } else {
    const maxStep = Math.floor((2 * limit) / (n - 1));
    const step = rand() < 0.15 ? 0 : pick(-Math.min(maxStep, size === 'large' ? 2000 : 4), Math.min(maxStep, size === 'large' ? 2000 : 4));
    const span = Math.abs(step) * (n - 1);
    const first = step >= 0 ? pick(-limit, limit - span) : pick(-limit + span, limit);
    arr = Array.from({ length: n }, (_, k) => first + k * step);
    if (roll > 0.6) {
      const at = Math.floor(rand() * n);
      const moved = arr[at] + (rand() < 0.5 ? 1 : -1);
      if (moved >= -limit && moved <= limit) arr[at] = moved;
    }
  }
  for (let k = n - 1; k > 0; k--) {
    const j = Math.floor(rand() * (k + 1));
    [arr[k], arr[j]] = [arr[j], arr[k]];
  }
  return [arr];
}
